24|void _cbor_builder_append(cbor_item_t* item,
25|                          struct _cbor_decoder_context* ctx) {
26|  if (ctx->stack->size == 0) {
27|    /* Top level item */
28|    ctx->root = item;
29|    return;
30|  }
31|  /* Part of a bigger structure */
32|  switch (ctx->stack->top->item->type) {
33|    // Handle Arrays and Maps since they can contain subitems of any type.
34|    // Byte/string construction from chunks is handled in the respective chunk
35|    // handlers.
36|    case CBOR_TYPE_ARRAY: {
37|      if (cbor_array_is_definite(ctx->stack->top->item)) {
38|        // We don't need an explicit check for whether the item still belongs
39|        // into this array because if there are extra items, they will cause a
40|        // syntax error when decoded.
41|        CBOR_ASSERT(ctx->stack->top->subitems > 0);
42|        // This should never happen since the definite array should be
43|        // preallocated for the expected number of items.
44|        if (!cbor_array_push(ctx->stack->top->item, item)) {
45|          ctx->creation_failed = true;
46|          cbor_decref(&item);
47|          break;
48|        }
49|        cbor_decref(&item);
50|        ctx->stack->top->subitems--;
51|        if (ctx->stack->top->subitems == 0) {
52|          cbor_item_t* stack_item = ctx->stack->top->item;
53|          _cbor_stack_pop(ctx->stack);
54|          _cbor_builder_append(stack_item, ctx);
55|        }
56|      } else {
57|        /* Indefinite array, don't bother with subitems */
58|        if (!cbor_array_push(ctx->stack->top->item, item)) {
59|          ctx->creation_failed = true;
60|        }
61|        cbor_decref(&item);
62|      }
63|      break;
64|    }
65|    case CBOR_TYPE_MAP: {
66|      // Handle both definite and indefinite maps the same initially.
67|      // Note: We use 0 and 1 subitems to distinguish between keys and values in
68|      // indefinite items
69|      if (ctx->stack->top->subitems % 2) {
70|        // Odd record, this is a value.
71|        ctx->creation_failed =
72|            !_cbor_map_add_value(ctx->stack->top->item, item);
73|        // Adding a value never fails since the memory is allocated when the
74|        // key is added
75|        CBOR_ASSERT(!ctx->creation_failed);
76|      } else {
77|        // Even record, this is a key.
78|        if (!_cbor_map_add_key(ctx->stack->top->item, item)) {
79|          ctx->creation_failed = true;
80|          cbor_decref(&item);
81|          break;
82|        }
83|      }
84|      cbor_decref(&item);
85|      if (cbor_map_is_definite(ctx->stack->top->item)) {
86|        CBOR_ASSERT(ctx->stack->top->subitems > 0);
87|        ctx->stack->top->subitems--;
88|        if (ctx->stack->top->subitems == 0) {
89|          cbor_item_t* map_entry = ctx->stack->top->item;
90|          _cbor_stack_pop(ctx->stack);
91|          _cbor_builder_append(map_entry, ctx);
92|        }
93|      } else {
94|        ctx->stack->top->subitems ^=
95|            1; /* Flip the indicator for indefinite items */
96|      }
97|      break;
98|    }
99|    case CBOR_TYPE_TAG: {
100|      CBOR_ASSERT(ctx->stack->top->subitems == 1);
101|      cbor_tag_set_item(ctx->stack->top->item, item);
102|      cbor_decref(&item); /* Give up on our reference */
103|      cbor_item_t* tagged_item = ctx->stack->top->item;
104|      _cbor_stack_pop(ctx->stack);
105|      _cbor_builder_append(tagged_item, ctx);
106|      break;
107|    }
108|    // We have an item to append but nothing to append it to.
109|    default: {
110|      cbor_decref(&item);
111|      ctx->syntax_error = true;
112|    }
113|  }
114|}

487|static void _cbor_nested_describe(cbor_item_t* item, FILE* out, int indent) {
488|  CBOR_ASSERT(cbor_typeof(item) >= CBOR_TYPE_UINT &&
489|              cbor_typeof(item) <= CBOR_TYPE_FLOAT_CTRL);
490|  const int indent_offset = 4;
491|  switch (cbor_typeof(item)) {
492|    case CBOR_TYPE_UINT: {
493|      _cbor_type_marquee(out, "CBOR_TYPE_UINT", indent);
494|      fprintf(out, "Width: %dB, ", _pow(2, cbor_int_get_width(item)));
495|      fprintf(out, "Value: %" PRIu64 "\n", cbor_get_int(item));
496|      break;
497|    }
498|    case CBOR_TYPE_NEGINT: {
499|      _cbor_type_marquee(out, "CBOR_TYPE_NEGINT", indent);
500|      fprintf(out, "Width: %dB, ", _pow(2, cbor_int_get_width(item)));
501|      fprintf(out, "Value: -%" PRIu64 " - 1\n", cbor_get_int(item));
502|      break;
503|    }
504|    case CBOR_TYPE_BYTESTRING: {
505|      _cbor_type_marquee(out, "CBOR_TYPE_BYTESTRING", indent);
506|      if (cbor_bytestring_is_indefinite(item)) {
507|        fprintf(out, "Indefinite, Chunks: %zu, Chunk data:\n",
508|                cbor_bytestring_chunk_count(item));
509|        for (size_t i = 0; i < cbor_bytestring_chunk_count(item); i++)
510|          _cbor_nested_describe(cbor_bytestring_chunks_handle(item)[i], out,
511|                                indent + indent_offset);
512|      } else {
513|        const unsigned char* data = cbor_bytestring_handle(item);
514|        fprintf(out, "Definite, Length: %zuB, Data:\n",
515|                cbor_bytestring_length(item));
516|        fprintf(out, "%*s", indent + indent_offset, " ");
517|        for (size_t i = 0; i < cbor_bytestring_length(item); i++)
518|          fprintf(out, "%02x", (int)(data[i] & 0xff));
519|        fprintf(out, "\n");
520|      }
521|      break;
522|    }
523|    case CBOR_TYPE_STRING: {
524|      _cbor_type_marquee(out, "CBOR_TYPE_STRING", indent);
525|      if (cbor_string_is_indefinite(item)) {
526|        fprintf(out, "Indefinite, Chunks: %zu, Chunk data:\n",
527|                cbor_string_chunk_count(item));
528|        for (size_t i = 0; i < cbor_string_chunk_count(item); i++)
529|          _cbor_nested_describe(cbor_string_chunks_handle(item)[i], out,
530|                                indent + indent_offset);
531|      } else {
532|        fprintf(out, "Definite, Length: %zuB, Codepoints: %zu, Data:\n",
533|                cbor_string_length(item), cbor_string_codepoint_count(item));
534|        fprintf(out, "%*s", indent + indent_offset, " ");
535|        // Note: The string is not escaped, whitespace and control character
536|        // will be printed in verbatim and take effect.
537|        // Empty strings may have a NULL handle
538|        if (cbor_string_length(item) > 0) {
539|          fwrite(cbor_string_handle(item), sizeof(unsigned char),
540|                 cbor_string_length(item), out);
541|        }
542|        fprintf(out, "\n");
543|      }
544|      break;
545|    }
546|    case CBOR_TYPE_ARRAY: {
547|      _cbor_type_marquee(out, "CBOR_TYPE_ARRAY", indent);
548|      if (cbor_array_is_definite(item)) {
549|        fprintf(out, "Definite, Size: %zu, Contents:\n", cbor_array_size(item));
550|      } else {
551|        fprintf(out, "Indefinite, Size: %zu, Contents:\n",
552|                cbor_array_size(item));
553|      }
554|
555|      for (size_t i = 0; i < cbor_array_size(item); i++)
556|        _cbor_nested_describe(cbor_array_handle(item)[i], out,
557|                              indent + indent_offset);
558|      break;
559|    }
560|    case CBOR_TYPE_MAP: {
561|      _cbor_type_marquee(out, "CBOR_TYPE_MAP", indent);
562|      if (cbor_map_is_definite(item)) {
563|        fprintf(out, "Definite, Size: %zu, Contents:\n", cbor_map_size(item));
564|      } else {
565|        fprintf(out, "Indefinite, Size: %zu, Contents:\n", cbor_map_size(item));
566|      }
567|
568|      // TODO: Label and group keys and values
569|      for (size_t i = 0; i < cbor_map_size(item); i++) {
570|        fprintf(out, "%*sMap entry %zu\n", indent + indent_offset, " ", i);
571|        _cbor_nested_describe(cbor_map_handle(item)[i].key, out,
572|                              indent + 2 * indent_offset);
573|        _cbor_nested_describe(cbor_map_handle(item)[i].value, out,
574|                              indent + 2 * indent_offset);
575|      }
576|      break;
577|    }
578|    case CBOR_TYPE_TAG: {
579|      _cbor_type_marquee(out, "CBOR_TYPE_TAG", indent);
580|      fprintf(out, "Value: %" PRIu64 "\n", cbor_tag_value(item));
581|      _cbor_nested_describe(cbor_move(cbor_tag_item(item)), out,
582|                            indent + indent_offset);
583|      break;
584|    }
585|    case CBOR_TYPE_FLOAT_CTRL: {
586|      _cbor_type_marquee(out, "CBOR_TYPE_FLOAT_CTRL", indent);
587|      if (cbor_float_ctrl_is_ctrl(item)) {
588|        if (cbor_is_bool(item))
589|          fprintf(out, "Bool: %s\n", cbor_get_bool(item) ? "true" : "false");
590|        else if (cbor_is_undef(item))
591|          fprintf(out, "Undefined\n");
592|        else if (cbor_is_null(item))
593|          fprintf(out, "Null\n");
594|        else
595|          fprintf(out, "Simple value: %d\n", cbor_ctrl_value(item));
596|      } else {
597|        fprintf(out, "Width: %dB, ", _pow(2, cbor_float_get_width(item)));
598|        fprintf(out, "Value: %lf\n", cbor_float_get_float(item));
599|      }
600|      break;
601|    }
602|  }
