16|cbor_item_t* cbor_load(cbor_data source, size_t source_size,
17|                       struct cbor_load_result* result) {
18|  /* Context stack */
19|  static struct cbor_callbacks callbacks = {
20|      .uint8 = &cbor_builder_uint8_callback,
21|      .uint16 = &cbor_builder_uint16_callback,
22|      .uint32 = &cbor_builder_uint32_callback,
23|      .uint64 = &cbor_builder_uint64_callback,
24|
25|      .negint8 = &cbor_builder_negint8_callback,
26|      .negint16 = &cbor_builder_negint16_callback,
27|      .negint32 = &cbor_builder_negint32_callback,
28|      .negint64 = &cbor_builder_negint64_callback,
29|
30|      .byte_string = &cbor_builder_byte_string_callback,
31|      .byte_string_start = &cbor_builder_byte_string_start_callback,
32|
33|      .string = &cbor_builder_string_callback,
34|      .string_start = &cbor_builder_string_start_callback,
35|
36|      .array_start = &cbor_builder_array_start_callback,
37|      .indef_array_start = &cbor_builder_indef_array_start_callback,
38|
39|      .map_start = &cbor_builder_map_start_callback,
40|      .indef_map_start = &cbor_builder_indef_map_start_callback,
41|
42|      .tag = &cbor_builder_tag_callback,
43|
44|      .null = &cbor_builder_null_callback,
45|      .undefined = &cbor_builder_undefined_callback,
46|      .boolean = &cbor_builder_boolean_callback,
47|      .float2 = &cbor_builder_float2_callback,
48|      .float4 = &cbor_builder_float4_callback,
49|      .float8 = &cbor_builder_float8_callback,
50|      .indef_break = &cbor_builder_indef_break_callback,
51|      .simple_value = &cbor_builder_simple_value_callback};
52|
53|  if (source_size == 0) {
54|    result->error.code = CBOR_ERR_NODATA;
55|    return NULL;
56|  }
57|  struct _cbor_stack stack = _cbor_stack_init();
58|
59|  /* Target for callbacks */
60|  struct _cbor_decoder_context context = (struct _cbor_decoder_context){
61|      .stack = &stack, .creation_failed = false, .syntax_error = false};
62|  struct cbor_decoder_result decode_result;
63|  *result =
64|      (struct cbor_load_result){.read = 0, .error = {.code = CBOR_ERR_NONE}};
65|
66|  do {
67|    if (source_size > result->read) { /* Check for overflows */
68|      decode_result =
69|          cbor_stream_decode(source + result->read, source_size - result->read,
70|                             &callbacks, &context);
71|    } else {
72|      result->error = (struct cbor_error){.code = CBOR_ERR_NOTENOUGHDATA,
73|                                          .position = result->read};
74|      goto error;
75|    }
76|
77|    switch (decode_result.status) {
78|      case CBOR_DECODER_FINISHED:
79|        /* Everything OK */
80|        {
81|          result->read += decode_result.read;
82|          break;
83|        }
84|      case CBOR_DECODER_NEDATA:
85|        /* Not enough data to complete the current item */
86|        {
87|          result->error.code = CBOR_ERR_NOTENOUGHDATA;
88|          goto error;
89|        }
90|      case CBOR_DECODER_ERROR:
91|        /* Reserved/malformed item */
92|        {
93|          result->error.code = CBOR_ERR_MALFORMATED;
94|          goto error;
95|        }
96|    }
97|
98|    if (context.creation_failed) {
99|      /* Most likely unsuccessful allocation - our callback has failed */
100|      result->error.code = CBOR_ERR_MEMERROR;
101|      goto error;
102|    } else if (context.syntax_error) {
103|      result->error.code = CBOR_ERR_SYNTAXERROR;
104|      goto error;
105|    }
106|  } while (stack.size > 0);
107|
108|  return context.root;
109|
110|error:
111|  result->error.position = result->read;
112|  // debug_print("Failed with decoder error %d at %d\n", result->error.code,
113|  // result->error.position); cbor_describe(stack.top->item, stdout);
114|  /* Free the stack */
115|  while (stack.size > 0) {
116|    cbor_decref(&stack.top->item);
117|    _cbor_stack_pop(&stack);
118|  }
119|  return NULL;
