122|static cbor_item_t* _cbor_copy_int(cbor_item_t* item, bool negative) {
123|  CBOR_ASSERT(cbor_isa_uint(item) || cbor_isa_negint(item));
124|  CBOR_ASSERT(cbor_int_get_width(item) >= CBOR_INT_8 &&
125|              cbor_int_get_width(item) <= CBOR_INT_64);
126|  cbor_item_t* res = NULL;
127|  switch (cbor_int_get_width(item)) {
128|    case CBOR_INT_8:
129|      res = cbor_build_uint8(cbor_get_uint8(item));
130|      break;
131|    case CBOR_INT_16:
132|      res = cbor_build_uint16(cbor_get_uint16(item));
133|      break;
134|    case CBOR_INT_32:
135|      res = cbor_build_uint32(cbor_get_uint32(item));
136|      break;
137|    case CBOR_INT_64:
138|      res = cbor_build_uint64(cbor_get_uint64(item));
139|      break;
140|  }
141|
142|  if (res == NULL) return NULL;
143|  if (negative) cbor_mark_negint(res);
144|
145|  return res;
