167|cbor_item_t* cbor_copy(cbor_item_t* item) {
168|  CBOR_ASSERT_VALID_TYPE(cbor_typeof(item));
169|  switch (cbor_typeof(item)) {
170|    case CBOR_TYPE_UINT:
171|      return _cbor_copy_int(item, false);
172|    case CBOR_TYPE_NEGINT:
173|      return _cbor_copy_int(item, true);
174|    case CBOR_TYPE_BYTESTRING:
175|      if (cbor_bytestring_is_definite(item)) {
176|        return cbor_build_bytestring(cbor_bytestring_handle(item),
177|                                     cbor_bytestring_length(item));
178|      } else {
179|        cbor_item_t* res = cbor_new_indefinite_bytestring();
180|        if (res == NULL) {
181|          return NULL;
182|        }
183|
184|        for (size_t i = 0; i < cbor_bytestring_chunk_count(item); i++) {
185|          cbor_item_t* chunk_copy =
186|              cbor_copy(cbor_bytestring_chunks_handle(item)[i]);
187|          if (chunk_copy == NULL) {
188|            cbor_decref(&res);
189|            return NULL;
190|          }
191|          if (!cbor_bytestring_add_chunk(res, chunk_copy)) {
192|            cbor_decref(&chunk_copy);
193|            cbor_decref(&res);
194|            return NULL;
195|          }
196|          cbor_decref(&chunk_copy);
197|        }
198|        return res;
199|      }
200|    case CBOR_TYPE_STRING:
201|      if (cbor_string_is_definite(item)) {
202|        return cbor_build_stringn((const char*)cbor_string_handle(item),
203|                                  cbor_string_length(item));
204|      } else {
205|        cbor_item_t* res = cbor_new_indefinite_string();
206|        if (res == NULL) {
207|          return NULL;
208|        }
209|
210|        for (size_t i = 0; i < cbor_string_chunk_count(item); i++) {
211|          cbor_item_t* chunk_copy =
212|              cbor_copy(cbor_string_chunks_handle(item)[i]);
213|          if (chunk_copy == NULL) {
214|            cbor_decref(&res);
215|            return NULL;
216|          }
217|          if (!cbor_string_add_chunk(res, chunk_copy)) {
218|            cbor_decref(&chunk_copy);
219|            cbor_decref(&res);
220|            return NULL;
221|          }
222|          cbor_decref(&chunk_copy);
223|        }
224|        return res;
225|      }
226|    case CBOR_TYPE_ARRAY: {
227|      cbor_item_t* res;
228|      if (cbor_array_is_definite(item)) {
229|        res = cbor_new_definite_array(cbor_array_size(item));
230|      } else {
231|        res = cbor_new_indefinite_array();
232|      }
233|      if (res == NULL) {
234|        return NULL;
235|      }
236|
237|      for (size_t i = 0; i < cbor_array_size(item); i++) {
238|        cbor_item_t* entry_copy = cbor_copy(cbor_move(cbor_array_get(item, i)));
239|        if (entry_copy == NULL) {
240|          cbor_decref(&res);
241|          return NULL;
242|        }
243|        if (!cbor_array_push(res, entry_copy)) {
244|          cbor_decref(&entry_copy);
245|          cbor_decref(&res);
246|          return NULL;
247|        }
248|        cbor_decref(&entry_copy);
249|      }
250|      return res;
251|    }
252|    case CBOR_TYPE_MAP: {
253|      cbor_item_t* res;
254|      if (cbor_map_is_definite(item)) {
255|        res = cbor_new_definite_map(cbor_map_size(item));
256|      } else {
257|        res = cbor_new_indefinite_map();
258|      }
259|      if (res == NULL) {
260|        return NULL;
261|      }
262|
263|      struct cbor_pair* it = cbor_map_handle(item);
264|      for (size_t i = 0; i < cbor_map_size(item); i++) {
265|        cbor_item_t* key_copy = cbor_copy(it[i].key);
266|        if (key_copy == NULL) {
267|          cbor_decref(&res);
268|          return NULL;
269|        }
270|        cbor_item_t* value_copy = cbor_copy(it[i].value);
271|        if (value_copy == NULL) {
272|          cbor_decref(&res);
273|          cbor_decref(&key_copy);
274|          return NULL;
275|        }
276|        if (!cbor_map_add(res, (struct cbor_pair){.key = key_copy,
277|                                                  .value = value_copy})) {
278|          cbor_decref(&res);
279|          cbor_decref(&key_copy);
280|          cbor_decref(&value_copy);
281|          return NULL;
282|        }
283|        cbor_decref(&key_copy);
284|        cbor_decref(&value_copy);
285|      }
286|      return res;
287|    }
288|    case CBOR_TYPE_TAG: {
289|      cbor_item_t* item_copy = cbor_copy(cbor_move(cbor_tag_item(item)));
290|      if (item_copy == NULL) {
291|        return NULL;
292|      }
293|      cbor_item_t* tag = cbor_build_tag(cbor_tag_value(item), item_copy);
294|      cbor_decref(&item_copy);
295|      return tag;
296|    }
297|    case CBOR_TYPE_FLOAT_CTRL:
298|      return _cbor_copy_float_ctrl(item);
299|    default:  // LCOV_EXCL_START
300|      _CBOR_UNREACHABLE;
301|      return NULL;  // LCOV_EXCL_STOP
302|  }
