305|cbor_item_t* cbor_copy_definite(cbor_item_t* item) {
306|  CBOR_ASSERT_VALID_TYPE(cbor_typeof(item));
307|  switch (cbor_typeof(item)) {
308|    case CBOR_TYPE_UINT:
309|    case CBOR_TYPE_NEGINT:
310|      return cbor_copy(item);
311|    case CBOR_TYPE_BYTESTRING:
312|      if (cbor_bytestring_is_definite(item)) {
313|        return cbor_copy(item);
314|      } else {
315|        size_t total_length = 0;
316|        for (size_t i = 0; i < cbor_bytestring_chunk_count(item); i++) {
317|          size_t chunk_length =
318|              cbor_bytestring_length(cbor_bytestring_chunks_handle(item)[i]);
319|          if (!_cbor_safe_to_add(total_length, chunk_length)) {
320|            return NULL;
321|          }
322|          total_length += chunk_length;
323|        }
324|
325|        // malloc(0) may legitimately return NULL, so do not allocate when
326|        // the chunks are all empty; the handle will be NULL.
327|        unsigned char* combined_data = NULL;
328|        if (total_length > 0) {
329|          combined_data = _cbor_malloc(total_length);
330|          if (combined_data == NULL) {
331|            return NULL;
332|          }
333|        }
334|
335|        size_t offset = 0;
336|        for (size_t i = 0; i < cbor_bytestring_chunk_count(item); i++) {
337|          cbor_item_t* chunk = cbor_bytestring_chunks_handle(item)[i];
338|          size_t chunk_length = cbor_bytestring_length(chunk);
339|          // Empty chunks may have a NULL handle
340|          if (chunk_length > 0) {
341|            memcpy(combined_data + offset, cbor_bytestring_handle(chunk),
342|                   chunk_length);
343|          }
344|          offset += chunk_length;
345|        }
346|
347|        cbor_item_t* res = cbor_new_definite_bytestring();
348|        if (res == NULL) {
349|          _cbor_free(combined_data);
350|          return NULL;
351|        }
352|        cbor_bytestring_set_handle(res, combined_data, total_length);
353|        return res;
354|      }
355|    case CBOR_TYPE_STRING:
356|      if (cbor_string_is_definite(item)) {
357|        return cbor_copy(item);
358|      } else {
359|        size_t total_length = 0;
360|        for (size_t i = 0; i < cbor_string_chunk_count(item); i++) {
361|          size_t chunk_length =
362|              cbor_string_length(cbor_string_chunks_handle(item)[i]);
363|          if (!_cbor_safe_to_add(total_length, chunk_length)) {
364|            return NULL;
365|          }
366|          total_length += chunk_length;
367|        }
368|
369|        // malloc(0) may legitimately return NULL, so do not allocate when
370|        // the chunks are all empty; the handle will be NULL.
371|        unsigned char* combined_data = NULL;
372|        if (total_length > 0) {
373|          combined_data = _cbor_malloc(total_length);
374|          if (combined_data == NULL) {
375|            return NULL;
376|          }
377|        }
378|
379|        size_t offset = 0;
380|        for (size_t i = 0; i < cbor_string_chunk_count(item); i++) {
381|          cbor_item_t* chunk = cbor_string_chunks_handle(item)[i];
382|          size_t chunk_length = cbor_string_length(chunk);
383|          // Empty chunks may have a NULL handle
384|          if (chunk_length > 0) {
385|            memcpy(combined_data + offset, cbor_string_handle(chunk),
386|                   chunk_length);
387|          }
388|          offset += chunk_length;
389|        }
390|
391|        cbor_item_t* res = cbor_new_definite_string();
392|        if (res == NULL) {
393|          _cbor_free(combined_data);
394|          return NULL;
395|        }
396|        cbor_string_set_handle(res, combined_data, total_length);
397|        return res;
398|      }
399|    case CBOR_TYPE_ARRAY: {
400|      cbor_item_t* res = cbor_new_definite_array(cbor_array_size(item));
401|      if (res == NULL) {
402|        return NULL;
403|      }
404|
405|      for (size_t i = 0; i < cbor_array_size(item); i++) {
406|        cbor_item_t* entry_copy =
407|            cbor_copy_definite(cbor_array_handle(item)[i]);
408|        if (entry_copy == NULL) {
409|          cbor_decref(&res);
410|          return NULL;
411|        }
412|        // Cannot fail since we have a definite array preallocated
413|        // cppcheck-suppress syntaxError
414|        const bool item_pushed _CBOR_UNUSED = cbor_array_push(res, entry_copy);
415|        CBOR_ASSERT(item_pushed);
416|        cbor_decref(&entry_copy);
417|      }
418|      return res;
419|    }
420|    case CBOR_TYPE_MAP: {
421|      cbor_item_t* res;
422|      res = cbor_new_definite_map(cbor_map_size(item));
423|      if (res == NULL) {
424|        return NULL;
425|      }
426|
427|      struct cbor_pair* it = cbor_map_handle(item);
428|      for (size_t i = 0; i < cbor_map_size(item); i++) {
429|        cbor_item_t* key_copy = cbor_copy_definite(it[i].key);
430|        if (key_copy == NULL) {
431|          cbor_decref(&res);
432|          return NULL;
433|        }
434|        cbor_item_t* value_copy = cbor_copy_definite(it[i].value);
435|        if (value_copy == NULL) {
436|          cbor_decref(&res);
437|          cbor_decref(&key_copy);
438|          return NULL;
439|        }
440|        // Cannot fail since we have a definite map preallocated
441|        // cppcheck-suppress syntaxError
442|        const bool item_added _CBOR_UNUSED = cbor_map_add(
443|            res, (struct cbor_pair){.key = key_copy, .value = value_copy});
444|        CBOR_ASSERT(item_added);
445|        cbor_decref(&key_copy);
446|        cbor_decref(&value_copy);
447|      }
448|      return res;
449|    }
450|    case CBOR_TYPE_TAG: {
451|      cbor_item_t* item_copy =
452|          cbor_copy_definite(cbor_move(cbor_tag_item(item)));
453|      if (item_copy == NULL) {
454|        return NULL;
455|      }
456|      cbor_item_t* tag = cbor_build_tag(cbor_tag_value(item), item_copy);
457|      cbor_decref(&item_copy);
458|      return tag;
459|    }
460|    case CBOR_TYPE_FLOAT_CTRL:
461|      return cbor_copy(item);
462|    default:  // LCOV_EXCL_START
463|      _CBOR_UNREACHABLE;
464|      return NULL;  // LCOV_EXCL_STOP
465|  }
