172|size_t cbor_serialize_alloc(const cbor_item_t* item, unsigned char** buffer,
173|                            size_t* buffer_size) {
174|  *buffer = NULL;
175|  size_t serialized_size = cbor_serialized_size(item);
176|  if (serialized_size == 0) {
177|    if (buffer_size != NULL) *buffer_size = 0;
178|    return 0;
179|  }
180|  *buffer = _cbor_malloc(serialized_size);
181|  if (*buffer == NULL) {
182|    if (buffer_size != NULL) *buffer_size = 0;
183|    return 0;
184|  }
185|
186|  size_t written = cbor_serialize(item, *buffer, serialized_size);
187|  CBOR_ASSERT(written == serialized_size);
188|  if (buffer_size != NULL) *buffer_size = serialized_size;
189|  return written;
