234|size_t cbor_serialize_bytestring(const cbor_item_t* item, unsigned char* buffer,
235|                                 size_t buffer_size) {
236|  CBOR_ASSERT(cbor_isa_bytestring(item));
237|  if (cbor_bytestring_is_definite(item)) {
238|    size_t length = cbor_bytestring_length(item);
239|    size_t written = cbor_encode_bytestring_start(length, buffer, buffer_size);
240|    if (written > 0 && (buffer_size - written >= length)) {
241|      // Empty bytestrings may have a NULL handle
242|      if (length > 0) {
243|        memcpy(buffer + written, cbor_bytestring_handle(item), length);
244|      }
245|      return written + length;
246|    }
247|    return 0;
248|  } else {
249|    CBOR_ASSERT(cbor_bytestring_is_indefinite(item));
250|    size_t chunk_count = cbor_bytestring_chunk_count(item);
251|    size_t written = cbor_encode_indef_bytestring_start(buffer, buffer_size);
252|    if (written == 0) return 0;
253|
254|    cbor_item_t** chunks = cbor_bytestring_chunks_handle(item);
255|    for (size_t i = 0; i < chunk_count; i++) {
256|      size_t chunk_written = cbor_serialize_bytestring(
257|          chunks[i], buffer + written, buffer_size - written);
258|      if (chunk_written == 0) return 0;
259|      written += chunk_written;
260|    }
261|
262|    size_t break_written =
263|        cbor_encode_break(buffer + written, buffer_size - written);
264|    if (break_written == 0) return 0;
265|    return written + break_written;
266|  }
