116|#define CHECK_RES(ctx, res)        \
117|  do {                             \
118|    if (res == NULL) {             \
119|      ctx->creation_failed = true; \
120|      return;                      \
121|    }                              \
122|  } while (0)
123|
124|// Check that the length fits into size_t. If not, we cannot possibly allocate
125|// the required memory and should fail fast. On 64-bit platforms size_t and
126|// uint64_t are the same width so this check is always false; it guards against
127|// oversized values on 32-bit platforms where SIZE_MAX < UINT64_MAX.
128|#define CHECK_LENGTH(ctx, length)  \
129|  do {                             \
130|    if (length > SIZE_MAX) {       \
131|      ctx->creation_failed = true; \
132|      return;                      \
133|    }                              \
134|  } while (0)
135|
136|#define PUSH_CTX_STACK(ctx, res, subitems)                     \
137|  do {                                                         \
138|    if (_cbor_stack_push(ctx->stack, res, subitems) == NULL) { \
139|      cbor_decref(&res);                                       \
140|      ctx->creation_failed = true;                             \
141|    }                                                          \
142|  } while (0)
