216|void cbor_builder_byte_string_callback(void* context, cbor_data data,
217|                                       uint64_t length) {
218|  struct _cbor_decoder_context* ctx = context;
219|  CHECK_LENGTH(ctx, length);
220|  // malloc(0) may legitimately return NULL, so do not allocate for an empty
221|  // chunk; the handle will be NULL and never dereferenced.
222|  unsigned char* new_handle = NULL;
223|  if (length > 0) {
224|    new_handle = _cbor_malloc(length);
225|    if (new_handle == NULL) {
226|      ctx->creation_failed = true;
227|      return;
228|    }
229|    memcpy(new_handle, data, length);
230|  }
231|  cbor_item_t* new_chunk = cbor_new_definite_bytestring();
232|
233|  if (new_chunk == NULL) {
234|    _cbor_free(new_handle);
235|    ctx->creation_failed = true;
236|    return;
237|  }
238|
239|  cbor_bytestring_set_handle(new_chunk, new_handle, length);
240|
241|  // If an indef bytestring is on the stack, extend it (if it were closed, it
242|  // would have been popped). Handle any syntax errors upstream.
243|  if (ctx->stack->size > 0 && cbor_isa_bytestring(ctx->stack->top->item) &&
244|      cbor_bytestring_is_indefinite(ctx->stack->top->item)) {
245|    if (!cbor_bytestring_add_chunk(ctx->stack->top->item, new_chunk)) {
246|      ctx->creation_failed = true;
247|    }
248|    cbor_decref(&new_chunk);
249|  } else {
250|    _cbor_builder_append(new_chunk, ctx);
251|  }
252|}
