348|/**
349| * Is the (partially constructed) item indefinite?
350| */
351|bool _cbor_is_indefinite(cbor_item_t* item) {
352|  switch (item->type) {
353|    case CBOR_TYPE_BYTESTRING:
354|      return cbor_bytestring_is_indefinite(item);
355|    case CBOR_TYPE_STRING:
356|      return cbor_string_is_indefinite(item);
357|    case CBOR_TYPE_ARRAY:
358|      return cbor_array_is_indefinite(item);
359|    case CBOR_TYPE_MAP:
360|      return cbor_map_is_indefinite(item);
361|    default:
362|      // Should never happen since a non-nested item cannot be on top of the
363|      // stack.
364|      return false;
365|  }
366|}
