368|void cbor_builder_indef_break_callback(void* context) {
369|  struct _cbor_decoder_context* ctx = context;
370|  /* There must be an item to break out of*/
371|  if (ctx->stack->size > 0) {
372|    cbor_item_t* item = ctx->stack->top->item;
373|    if (_cbor_is_indefinite(
374|            item) && /* Only indefinite items can be terminated by 0xFF */
375|        /* Special case: we cannot append up if an indefinite map is incomplete
376|           (we are expecting a value). */
377|        (item->type != CBOR_TYPE_MAP || ctx->stack->top->subitems % 2 == 0)) {
378|      _cbor_stack_pop(ctx->stack);
379|      _cbor_builder_append(item, ctx);
380|      return;
381|    }
382|  }
383|
384|  ctx->syntax_error = true;
385|}
