557|static void test_serialize_unassigned_ctrl(void** _state _CBOR_UNUSED) {
558|  // Unassigned simple values on both sides of the one-byte/two-byte boundary
559|  cbor_item_t* item = cbor_build_ctrl(0);
560|  assert_size_equal(1, cbor_serialize(item, buffer, 512));
561|  assert_memory_equal(buffer, ((unsigned char[]){0xE0}), 1);
562|  assert_size_equal(cbor_serialized_size(item), 1);
563|  cbor_decref(&item);
564|
565|  item = cbor_build_ctrl(19);
566|  assert_size_equal(1, cbor_serialize(item, buffer, 512));
567|  assert_memory_equal(buffer, ((unsigned char[]){0xF3}), 1);
568|  assert_size_equal(cbor_serialized_size(item), 1);
569|  cbor_decref(&item);
570|
571|  item = cbor_build_ctrl(32);
572|  assert_size_equal(2, cbor_serialize(item, buffer, 512));
573|  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0x20}), 2);
574|  assert_size_equal(cbor_serialized_size(item), 2);
575|  cbor_decref(&item);
576|}

